pub(super) fn ppc_res_type_text(res_type: u32) -> String {
    let bytes = res_type.to_be_bytes();
    if bytes
        .iter()
        .all(|byte| byte.is_ascii_graphic() || *byte == b' ')
    {
        String::from_utf8_lossy(&bytes).into_owned()
    } else {
        format!("${res_type:08X}")
    }
}

